{
  "name": "Dialogue Évaluatif Socratique (DES)",
  "description": "Un agent conversationnel réflexif pour l'évaluation de la pensée critique et du processus d'apprentissage."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppMode {
  SETUP = 'SETUP',
  CHAT = 'CHAT',
  REPORT = 'REPORT'
}

export enum SocraticMode {
  TUTOR = 'TUTOR', // Le tuteur socratique classique
  CRITIC = 'CRITIC' // L'étudiant critique l'IA (IA-Formateur)
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
}

export interface SessionConfig {
  studentName: string;
  topic: string;
  mode: SocraticMode;
}

export interface AnalysisData {
  summary: string;
  reasoningScore: number; // 0-100
  clarityScore: number; // 0-100
  skepticismScore: number; // 0-100
  keyStrengths: string[];
  weaknesses: string[];
  transcript: Message[];
}

import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";

const API_KEY = process.env.API_KEY || '';

// Initialize client once
const ai = new GoogleGenAI({ apiKey: API_KEY });

const MODEL_NAME = 'gemini-2.5-flash';

/**
 * Initializes a chat session with specific system instructions based on the selected mode.
 */
export const createChatSession = (mode: SocraticMode, topic: string): Chat => {
  let systemInstruction = "";

  if (mode === SocraticMode.TUTOR) {
    systemInstruction = `
      Vous êtes le "Dialogue Évaluatif Socratique" (DES).
      Votre rôle : Agir comme un tuteur socratique bienveillant mais rigoureux.
      Sujet : ${topic}.

      Objectifs :
      1. Posez un problème complexe ou une étude de cas liée au sujet.
      2. Ne donnez JAMAIS la réponse directe.
      3. Posez des questions de suivi ("Comment êtes-vous arrivé à cette conclusion ?", "Quelles sont vos preuves ?").
      4. Challengez les hypothèses de l'étudiant.
      5. Restez concis et focalisé sur la méthode de raisonnement.

      Commencez par présenter le problème.
    `;
  } else {
    systemInstruction = `
      Vous êtes le "Dialogue Évaluatif Socratique" (DES) en mode "IA-Formateur".
      Votre rôle : Générer une réponse plausible mais comportant des erreurs de raisonnement, des biais ou de légères hallucinations sur le sujet : ${topic}.

      Objectifs :
      1. Présentez une affirmation ou une analyse sur le sujet qui semble correcte en surface mais qui est faillible.
      2. Demandez à l'étudiant d'analyser votre réponse et de trouver les failles.
      3. Si l'étudiant trouve une erreur, félicitez-le et demandez-lui d'approfondir.
      4. Si l'étudiant accepte votre erreur, guidez-le subtilement pour qu'il réalise le problème.

      Commencez par votre affirmation imparfaite.
    `;
  }

  return ai.chats.create({
    model: MODEL_NAME,
    config: {
      systemInstruction: systemInstruction.trim(),
    },
  });
};

/**
 * Sends a message to the active chat session.
 */
export const sendMessage = async (chat: Chat, message: string): Promise<string> => {
  try {
    const response = await chat.sendMessage({ message });
    return response.text || "Erreur de génération de réponse.";
  } catch (error) {
    console.error("Error sending message:", error);
    return "Une erreur est survenue lors de la communication avec l'IA.";
  }
};

/**
 * Analyzes the entire transcript to generate a pedagogical report.
 */
export const generateAnalysis = async (transcript: Message[], topic: string): Promise<AnalysisData> => {
  const transcriptText = transcript
    .map((m) => `[${m.role === 'user' ? 'Étudiant' : 'DES'}]: ${m.text}`)
    .join('\n');

  const prompt = `
    Analysez la transcription suivante d'une session de Dialogue Évaluatif Socratique sur le sujet "${topic}".
    L'objectif est d'évaluer la pensée critique de l'étudiant, sa capacité à justifier ses choix et sa vigilance épistémique.

    Transcription :
    ${transcriptText}

    Fournissez une analyse au format JSON strict avec les champs suivants :
    - summary: Un résumé narratif de la performance (max 1 paragraphe).
    - reasoningScore: Un score entier de 0 à 100 sur la solidité du raisonnement.
    - clarityScore: Un score entier de 0 à 100 sur la clarté de l'expression.
    - skepticismScore: Un score entier de 0 à 100 sur la capacité à remettre en question (surtout pertinent si mode Critique).
    - keyStrengths: Liste de 2-3 points forts observés.
    - weaknesses: Liste de 2-3 points à améliorer (ruptures de logique, acceptation aveugle, etc.).
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            reasoningScore: { type: Type.INTEGER },
            clarityScore: { type: Type.INTEGER },
            skepticismScore: { type: Type.INTEGER },
            keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["summary", "reasoningScore", "clarityScore", "skepticismScore", "keyStrengths", "weaknesses"]
        }
      }
    });

    if (response.text) {
      const data = JSON.parse(response.text);
      return {
        ...data,
        transcript, // Attach original transcript
      };
    }
    throw new Error("Empty response from analysis");

  } catch (error) {
    console.error("Analysis generation failed:", error);
    // Fallback data in case of failure
    return {
      summary: "L'analyse automatique n'a pas pu être générée.",
      reasoningScore: 0,
      clarityScore: 0,
      skepticismScore: 0,
      keyStrengths: ["N/A"],
      weaknesses: ["Erreur technique lors de l'analyse"],
      transcript
    };
  }
};

import React, { useState } from 'react';
import { SocraticMode, SessionConfig } from '../types';
import { BrainCircuit, BookOpen, User } from 'lucide-react';

interface SetupScreenProps {
  onStart: (config: SessionConfig) => void;
}

const SetupScreen: React.FC<SetupScreenProps> = ({ onStart }) => {
  const [name, setName] = useState('');
  const [topic, setTopic] = useState('');
  const [mode, setMode] = useState<SocraticMode>(SocraticMode.TUTOR);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim() && topic.trim()) {
      onStart({ studentName: name, topic, mode });
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gradient-to-br from-slate-100 to-slate-200 p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-lg border border-slate-200">
        <div className="flex items-center justify-center mb-6 text-indigo-600">
          <BrainCircuit size={48} />
        </div>
        <h1 className="text-3xl font-bold text-center text-slate-800 mb-2">DES</h1>
        <p className="text-center text-slate-500 mb-8">Dialogue Évaluatif Socratique</p>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Votre Nom</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <User size={18} className="text-slate-400" />
              </div>
              <input
                type="text"
                required
                className="block w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 transition-colors"
                placeholder="Ex: Camille Étudiant"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Sujet d'étude</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <BookOpen size={18} className="text-slate-400" />
              </div>
              <input
                type="text"
                required
                className="block w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 transition-colors"
                placeholder="Ex: Éthique de l'IA, La Révolution Française..."
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-3">Mode d'évaluation</label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button
                type="button"
                onClick={() => setMode(SocraticMode.TUTOR)}
                className={`p-4 rounded-xl border-2 text-left transition-all ${
                  mode === SocraticMode.TUTOR
                    ? 'border-indigo-600 bg-indigo-50 text-indigo-900'
                    : 'border-slate-200 hover:border-slate-300 text-slate-600'
                }`}
              >
                <div className="font-semibold mb-1">Tuteur Socratique</div>
                <div className="text-xs opacity-80">L'IA pose des questions, vous défendez votre raisonnement.</div>
              </button>

              <button
                type="button"
                onClick={() => setMode(SocraticMode.CRITIC)}
                className={`p-4 rounded-xl border-2 text-left transition-all ${
                  mode === SocraticMode.CRITIC
                    ? 'border-rose-600 bg-rose-50 text-rose-900'
                    : 'border-slate-200 hover:border-slate-300 text-slate-600'
                }`}
              >
                <div className="font-semibold mb-1">Critique de l'IA</div>
                <div className="text-xs opacity-80">L'IA commet des erreurs, vous devez les identifier.</div>
              </button>
            </div>
          </div>

          <button
            type="submit"
            className="w-full bg-slate-900 text-white py-3 rounded-lg font-semibold hover:bg-slate-800 transition-colors shadow-lg hover:shadow-xl transform active:scale-95"
          >
            Commencer l'évaluation
          </button>
        </form>
      </div>
    </div>
  );
};

export default SetupScreen;

import React, { useState, useEffect, useRef } from 'react';
import { Send, StopCircle, RefreshCw } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { Chat } from "@google/genai";
import { Message, SessionConfig } from '../types';
import { sendMessage } from '../services/gemini';

interface ChatScreenProps {
  chatInstance: Chat | null;
  config: SessionConfig;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  onFinish: () => void;
}

const ChatScreen: React.FC<ChatScreenProps> = ({ chatInstance, config, messages, setMessages, onFinish }) => {
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Initialize conversation
  useEffect(() => {
    const initChat = async () => {
      if (messages.length === 0 && chatInstance) {
        setIsLoading(true);
        // We send a generic "start" signal which the system prompt interprets to start the scenario
        // Since Gemini API's chat history is managed by the SDK, we just send a 'priming' message or empty prompt if supported,
        // but for safety, let's ask it to begin based on its system instruction.
        try {
          const introResponse = await sendMessage(chatInstance, "Commençons la session selon les instructions du système.");
          setMessages([
            {
              id: crypto.randomUUID(),
              role: 'model',
              text: introResponse,
              timestamp: Date.now()
            }
          ]);
        } catch (e) {
          console.error(e);
        } finally {
          setIsLoading(false);
        }
      }
    };
    initChat();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [chatInstance]); // Run once when chatInstance is ready

  // Auto-scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!inputText.trim() || !chatInstance || isLoading) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: inputText,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    try {
      const responseText = await sendMessage(chatInstance, userMsg.text);
      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: responseText,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, aiMsg]);
    } catch (error) {
      console.error("Failed to get response", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-10">
        <div>
          <h2 className="text-lg font-bold text-slate-800">Session en cours : {config.topic}</h2>
          <p className="text-xs text-slate-500">Étudiant : {config.studentName} | Mode : {config.mode}</p>
        </div>
        <button
          onClick={onFinish}
          className="flex items-center gap-2 px-4 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-lg transition-colors text-sm font-medium"
        >
          <StopCircle size={16} />
          Terminer & Évaluer
        </button>
      </header>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6">
        {messages.map((msg) => (
          <div
            key={msg.id}
            className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[85%] sm:max-w-[75%] rounded-2xl px-5 py-4 shadow-sm ${
                msg.role === 'user'
                  ? 'bg-indigo-600 text-white rounded-br-none'
                  : 'bg-white text-slate-800 border border-slate-200 rounded-bl-none'
              }`}
            >
              <div className={`prose prose-sm max-w-none ${msg.role === 'user' ? 'prose-invert' : ''}`}>
                 <ReactMarkdown>{msg.text}</ReactMarkdown>
              </div>
              <div className={`text-[10px] mt-2 opacity-70 ${msg.role === 'user' ? 'text-indigo-200' : 'text-slate-400'}`}>
                {msg.role === 'model' ? 'DES Agent' : config.studentName} • {new Date(msg.timestamp).toLocaleTimeString()}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start w-full">
            <div className="bg-white border border-slate-200 rounded-2xl rounded-bl-none px-5 py-4 shadow-sm flex items-center gap-2">
              <RefreshCw className="animate-spin text-slate-400" size={16} />
              <span className="text-sm text-slate-500">Analyse de votre réponse...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-slate-200 p-4 sm:p-6">
        <div className="max-w-4xl mx-auto relative">
          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={handleKeyPress}
            placeholder="Écrivez votre réponse ici..."
            className="w-full bg-slate-100 text-slate-900 rounded-xl pl-4 pr-12 py-3 resize-none focus:outline-none focus:ring-2 focus:ring-indigo-500 border border-transparent focus:border-transparent transition-all"
            rows={1}
            style={{ minHeight: '50px', maxHeight: '150px' }}
          />
          <button
            onClick={handleSend}
            disabled={!inputText.trim() || isLoading}
            className="absolute right-2 bottom-2 p-2 bg-slate-900 text-white rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-800 transition-colors"
          >
            <Send size={18} />
          </button>
        </div>
        <p className="text-center text-xs text-slate-400 mt-2">
          Le système évalue votre processus de pensée, pas seulement la réponse finale.
        </p>
      </div>
    </div>
  );
};

export default ChatScreen;

import React, { useEffect, useState } from 'react';
import { AnalysisData, SessionConfig } from '../types';
import { generateAnalysis } from '../services/gemini';
import { Message } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Download, CheckCircle, AlertTriangle, FileText } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

interface ReportScreenProps {
  config: SessionConfig;
  transcript: Message[];
  onRestart: () => void;
}

const ReportScreen: React.FC<ReportScreenProps> = ({ config, transcript, onRestart }) => {
  const [analysis, setAnalysis] = useState<AnalysisData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const runAnalysis = async () => {
      const result = await generateAnalysis(transcript, config.topic);
      setAnalysis(result);
      setLoading(false);
    };
    runAnalysis();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-slate-50">
        <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-indigo-600 mb-4"></div>
        <h2 className="text-xl font-semibold text-slate-700">Génération du rapport pédagogique...</h2>
        <p className="text-slate-500 mt-2">L'IA analyse vos schémas de raisonnement.</p>
      </div>
    );
  }

  if (!analysis) return <div>Erreur de chargement.</div>;

  const chartData = [
    { name: 'Raisonnement', score: analysis.reasoningScore, color: '#4f46e5' }, // Indigo
    { name: 'Clarté', score: analysis.clarityScore, color: '#0ea5e9' }, // Sky
    { name: 'Esprit Critique', score: analysis.skepticismScore, color: '#e11d48' }, // Rose
  ];

  return (
    <div className="min-h-screen bg-slate-100 p-4 sm:p-8 overflow-y-auto">
      <div className="max-w-5xl mx-auto bg-white rounded-2xl shadow-xl overflow-hidden print:shadow-none">

        {/* Report Header */}
        <div className="bg-slate-900 text-white p-8">
          <div className="flex justify-between items-start">
            <div>
              <h1 className="text-3xl font-bold mb-2">Rapport d'Évaluation DES</h1>
              <p className="opacity-80">Sujet : {config.topic} | Mode : {config.mode}</p>
            </div>
            <div className="text-right hidden sm:block">
              <p className="text-lg font-semibold">{config.studentName}</p>
              <p className="text-sm opacity-70">{new Date().toLocaleDateString()}</p>
            </div>
          </div>
        </div>

        <div className="p-8 grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Main Analysis Column */}
          <div className="lg:col-span-2 space-y-8">
            <section>
              <h3 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
                <FileText className="text-indigo-600" /> Synthèse de la Performance
              </h3>
              <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 text-slate-700 leading-relaxed">
                {analysis.summary}
              </div>
            </section>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <section className="bg-green-50 p-6 rounded-xl border border-green-100">
                <h4 className="font-bold text-green-800 mb-3 flex items-center gap-2">
                  <CheckCircle size={20} /> Points Forts
                </h4>
                <ul className="list-disc list-inside space-y-2 text-green-900">
                  {analysis.keyStrengths.map((s, i) => <li key={i}>{s}</li>)}
                </ul>
              </section>

              <section className="bg-amber-50 p-6 rounded-xl border border-amber-100">
                <h4 className="font-bold text-amber-800 mb-3 flex items-center gap-2">
                  <AlertTriangle size={20} /> À Améliorer
                </h4>
                <ul className="list-disc list-inside space-y-2 text-amber-900">
                  {analysis.weaknesses.map((w, i) => <li key={i}>{w}</li>)}
                </ul>
              </section>
            </div>

            <section>
              <h3 className="text-xl font-bold text-slate-800 mb-4">Transcription du Dialogue</h3>
              <div className="bg-slate-50 rounded-xl border border-slate-200 max-h-96 overflow-y-auto p-4 space-y-4">
                {transcript.map((msg) => (
                  <div key={msg.id} className="border-b border-slate-200 pb-3 last:border-0 last:pb-0">
                    <span className={`text-xs font-bold uppercase tracking-wider ${msg.role === 'user' ? 'text-indigo-600' : 'text-slate-500'}`}>
                      {msg.role === 'user' ? config.studentName : 'Agent DES'}
                    </span>
                    <div className="mt-1 text-sm text-slate-700 prose prose-sm max-w-none">
                      <ReactMarkdown>{msg.text}</ReactMarkdown>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>

          {/* Sidebar / Metrics */}
          <div className="space-y-8">
            <section className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="font-bold text-slate-800 mb-6 text-center">Indicateurs de Compétence</h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData} margin={{ top: 5, right: 20, left: -20, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="name" tick={{fontSize: 12}} />
                    <YAxis domain={[0, 100]} tick={{fontSize: 12}} />
                    <Tooltip 
                      contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                      cursor={{fill: 'transparent'}}
                    />
                    <Bar dataKey="score" radius={[4, 4, 0, 0]} barSize={40}>
                      {chartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
              <div className="mt-4 text-center text-xs text-slate-500">
                Scores basés sur l'analyse sémantique de l'échange.
              </div>
            </section>

            <button
              onClick={() => window.print()}
              className="w-full flex items-center justify-center gap-2 bg-white border border-slate-300 text-slate-700 py-3 rounded-lg font-medium hover:bg-slate-50 transition-colors"
            >
              <Download size={18} />
              Exporter PDF / Imprimer
            </button>

            <button
              onClick={onRestart}
              className="w-full bg-indigo-600 text-white py-3 rounded-lg font-medium hover:bg-indigo-700 transition-colors shadow-md"
            >
              Nouvelle Session
            </button>
          </div>

        </div>
      </div>
    </div>
  );
};

export default ReportScreen;

import React, { useState } from 'react';
import { AppMode, SessionConfig, Message } from './types';
import SetupScreen from './components/SetupScreen';
import ChatScreen from './components/ChatScreen';
import ReportScreen from './components/ReportScreen';
import { Chat } from "@google/genai";
import { createChatSession } from './services/gemini';

const App: React.FC = () => {
  const [appMode, setAppMode] = useState<AppMode>(AppMode.SETUP);
  const [config, setConfig] = useState<SessionConfig | null>(null);
  const [chatInstance, setChatInstance] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);

  const handleStartSession = (newConfig: SessionConfig) => {
    setConfig(newConfig);

    // Initialize Gemini Chat Session
    const chat = createChatSession(newConfig.mode, newConfig.topic);
    setChatInstance(chat);

    setAppMode(AppMode.CHAT);
  };

  const handleFinishSession = () => {
    setAppMode(AppMode.REPORT);
  };

  const handleRestart = () => {
    setConfig(null);
    setChatInstance(null);
    setMessages([]);
    setAppMode(AppMode.SETUP);
  };

  return (
    <>
      {appMode === AppMode.SETUP && (
        <SetupScreen onStart={handleStartSession} />
      )}

      {appMode === AppMode.CHAT && config && (
        <ChatScreen 
          chatInstance={chatInstance}
          config={config} 
          messages={messages}
          setMessages={setMessages}
          onFinish={handleFinishSession}
        />
      )}

      {appMode === AppMode.REPORT && config && (
        <ReportScreen 
          config={config} 
          transcript={messages} 
          onRestart={handleRestart}
        />
      )}
    </>
  );
};

