import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";

const API_KEY = process.env.API_KEY || '';

// Initialize client once
const ai = new GoogleGenAI({ apiKey: API_KEY });

const MODEL_NAME = 'gemini-2.5-flash';

/**
 * Initializes a chat session with specific system instructions based on the selected mode.
 */
export const createChatSession = (mode: SocraticMode, topic: string): Chat => {
  let systemInstruction = "";

  if (mode === SocraticMode.TUTOR) {
    systemInstruction = `
      Vous êtes le "Dialogue Évaluatif Socratique" (DES).
      Votre rôle : Agir comme un tuteur socratique bienveillant mais rigoureux.
      Sujet : ${topic}.

      Objectifs :
      1. Posez un problème complexe ou une étude de cas liée au sujet.
      2. Ne donnez JAMAIS la réponse directe.
      3. Posez des questions de suivi ("Comment êtes-vous arrivé à cette conclusion ?", "Quelles sont vos preuves ?").
      4. Challengez les hypothèses de l'étudiant.
      5. Restez concis et focalisé sur la méthode de raisonnement.

      Commencez par présenter le problème.
    `;
  } else {
    systemInstruction = `
      Vous êtes le "Dialogue Évaluatif Socratique" (DES) en mode "IA-Formateur".
      Votre rôle : Générer une réponse plausible mais comportant des erreurs de raisonnement, des biais ou de légères hallucinations sur le sujet : ${topic}.

      Objectifs :
      1. Présentez une affirmation ou une analyse sur le sujet qui semble correcte en surface mais qui est faillible.
      2. Demandez à l'étudiant d'analyser votre réponse et de trouver les failles.
      3. Si l'étudiant trouve une erreur, félicitez-le et demandez-lui d'approfondir.
      4. Si l'étudiant accepte votre erreur, guidez-le subtilement pour qu'il réalise le problème.

      Commencez par votre affirmation imparfaite.
    `;
  }

  return ai.chats.create({
    model: MODEL_NAME,
    config: {
      systemInstruction: systemInstruction.trim(),
    },
  });
};

/**
 * Sends a message to the active chat session.
 */
export const sendMessage = async (chat: Chat, message: string): Promise<string> => {
  try {
    const response = await chat.sendMessage({ message });
    return response.text || "Erreur de génération de réponse.";
  } catch (error) {
    console.error("Error sending message:", error);
    return "Une erreur est survenue lors de la communication avec l'IA.";
  }
};

/**
 * Analyzes the entire transcript to generate a pedagogical report.
 */
export const generateAnalysis = async (transcript: Message[], topic: string): Promise<AnalysisData> => {
  const transcriptText = transcript
    .map((m) => `[${m.role === 'user' ? 'Étudiant' : 'DES'}]: ${m.text}`)
    .join('\n');

  const prompt = `
    Analysez la transcription suivante d'une session de Dialogue Évaluatif Socratique sur le sujet "${topic}".
    L'objectif est d'évaluer la pensée critique de l'étudiant, sa capacité à justifier ses choix et sa vigilance épistémique.

    Transcription :
    ${transcriptText}

    IMPORTANT : TOUS les textes générés dans le JSON doivent impérativement être en FRANÇAIS.

    Fournissez une analyse au format JSON strict avec les champs suivants :
    - summary: Un résumé narratif de la performance (max 1 paragraphe) rédigé en français.
    - reasoningScore: Un score entier de 0 à 100 sur la solidité du raisonnement.
    - clarityScore: Un score entier de 0 à 100 sur la clarté de l'expression.
    - skepticismScore: Un score entier de 0 à 100 sur la capacité à remettre en question (surtout pertinent si mode Critique).
    - keyStrengths: Liste de 2-3 points forts observés (en français).
    - weaknesses: Liste de 2-3 points à améliorer (ruptures de logique, acceptation aveugle, etc.) (en français).
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            reasoningScore: { type: Type.INTEGER },
            clarityScore: { type: Type.INTEGER },
            skepticismScore: { type: Type.INTEGER },
            keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["summary", "reasoningScore", "clarityScore", "skepticismScore", "keyStrengths", "weaknesses"]
        }
      }
    });

    if (response.text) {
      const data = JSON.parse(response.text);
      return {
        ...data,
        transcript, // Attach original transcript
      };
    }
    throw new Error("Empty response from analysis");

  } catch (error) {
    console.error("Analysis generation failed:", error);
    // Fallback data in case of failure
    return {
      summary: "L'analyse automatique n'a pas pu être générée.",
      reasoningScore: 0,
      clarityScore: 0,
      skepticismScore: 0,
      keyStrengths: ["N/A"],
      weaknesses: ["Erreur technique lors de l'analyse"],
      transcript
    };
  }
};

