              <button
                onClick={handleCopyText}
                className="w-full flex items-center justify-center gap-2 bg-white border border-slate-300 text-slate-700 py-3 rounded-lg font-medium hover:bg-slate-50 transition-colors"
              >
                {copied ? <Check size={18} className="text-green-600" /> : <Copy size={18} />}
                {copied ? "Copié !" : "Copier le texte"}
              </button>
            </div>

            <hr className="border-slate-200" />

            <button
              onClick={onRestart}
              className="w-full bg-indigo-600 text-white py-3 rounded-lg font-medium hover:bg-indigo-700 transition-colors shadow-md"
            >
              Nouvelle Session
            </button>
          </div>

        </div>
      </div>
    </div>
  );
};

