import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";

const API_KEY = process.env.API_KEY || '';

// Initialize client once
const ai = new GoogleGenAI({ apiKey: API_KEY });

const MODEL_NAME = 'gemini-2.5-flash';

/**
 * Initializes a chat session with specific system instructions based on the selected mode.
 */
export const createChatSession = (mode: SocraticMode, topic: string): Chat => {
  let systemInstruction = "";

  if (mode === SocraticMode.TUTOR) {
    systemInstruction = `
      Vous êtes le "Dialogue Évaluatif Socratique" (DES).
      Votre rôle : Tuteur exigeant axé sur le PROCESSUS et la MÉTACOGNITION.
      Sujet : ${topic}.

      Protocole pédagogique strict :
      1. DEMANDE D'ÉBAUCHE : Ne demandez pas une réponse finale. Demandez d'abord un plan, une première ébauche ou une hypothèse de travail.
      2. JUSTIFICATION MÉTHODOLOGIQUE : Pour chaque affirmation de l'étudiant, demandez "Pourquoi avoir choisi cette approche ?" ou "Sur quelle preuve repose ce choix ?". Forcez l'étudiant à rendre sa pensée visible.
      3. CONTRADICTION (DÉFENSE ORALE) : Adoptez une posture contradictoire. Attaquez les points faibles de son raisonnement pour simuler une défense orale. L'étudiant doit défendre ses choix "sur le vif".
      4. JOURNAL RÉFLEXIF : Demandez régulièrement : "Avez-vous changé d'avis par rapport à votre idée initiale ? Pourquoi ?".

      Ne donnez JAMAIS la réponse. Évaluez la méthode, pas juste le résultat.
      Commencez par demander à l'étudiant de proposer une première piste de réflexion ou un plan sur le sujet.
    `;
  } else {
    systemInstruction = `
      Vous êtes le "Dialogue Évaluatif Socratique" (DES) en mode "IA-Formateur / Littératie Critique".
      Votre rôle : Générer du contenu plausible mais faillible pour tester la VIGILANCE ÉPISTÉMIQUE de l'étudiant.
      Sujet : ${topic}.

      Protocole pédagogique strict :
      1. LE PIÈGE : Générez une analyse détaillée sur le sujet qui contient des erreurs subtiles (biais logique, hallucination factuelle crédible, ou généralisation abusive).
      2. LA CONSIGNE : Demandez à l'étudiant d'agir comme un expert qui doit valider ce contenu avant publication. Demandez-lui de vérifier les faits et d'identifier les biais.
      3. VÉRIFICATION : Si l'étudiant corrige une erreur, demandez-lui : "Quelles sources avez-vous consultées pour vérifier cela ?" ou "Comment savez-vous que c'est faux ?".
      4. RESPONSABILITÉ : Poussez l'étudiant à critiquer la "boîte noire" de l'IA.

      Commencez par soumettre votre analyse (imparfaite) à l'étudiant.
    `;
  }

  return ai.chats.create({
    model: MODEL_NAME,
    config: {
      systemInstruction: systemInstruction.trim(),
    },
  });
};

/**
 * Sends a message to the active chat session.
 */
export const sendMessage = async (chat: Chat, message: string): Promise<string> => {
  try {
    const response = await chat.sendMessage({ message });
    return response.text || "Erreur de génération de réponse.";
  } catch (error) {
    console.error("Error sending message:", error);
    return "Une erreur est survenue lors de la communication avec l'IA.";
  }
};

/**
 * Analyzes the entire transcript to generate a pedagogical report.
 */
export const generateAnalysis = async (transcript: Message[], topic: string, aiDeclaration: string): Promise<AnalysisData> => {
  const transcriptText = transcript
    .map((m) => `[${m.role === 'user' ? 'Étudiant' : 'DES'}]: ${m.text}`)
    .join('\n');

  const prompt = `
    Analysez cette session de Dialogue Évaluatif Socratique.
    Sujet : "${topic}".

    Déclaration d'usage de l'IA par l'étudiant (Transparence/Agraphie) :
    "${aiDeclaration}"

    Transcription du dialogue :
    ${transcriptText}

    OBJECTIF D'ÉVALUATION :
    Vous devez évaluer le PROCESSUS D'APPRENTISSAGE et non seulement le produit final.
    Cherchez des preuves de :
    1. Itération : L'étudiant a-t-il affiné sa pensée ?
    2. Justification : L'étudiant a-t-il expliqué le "pourquoi" de ses choix ?
    3. Critique : L'étudiant a-t-il remis en cause l'IA ou ses propres biais ?
    4. Responsabilité : La déclaration d'usage est-elle cohérente avec le dialogue ?

    IMPORTANT : TOUS les textes générés dans le JSON doivent impérativement être en FRANÇAIS.

    Format JSON attendu :
    - summary: Résumé narratif axé sur l'évolution de la pensée de l'étudiant.
    - reasoningScore: (0-100) Solidité logique.
    - clarityScore: (0-100) Clarté d'expression.
    - skepticismScore: (0-100) Jugement critique face à l'information.
    - processScore: (0-100) Capacité à itérer, à corriger ses erreurs et à montrer son cheminement.
    - reflectionScore: (0-100) Capacité métacognitive (conscience de sa propre méthode).
    - keyStrengths: Points forts (ex: "Excellente vérification des sources", "Défense orale solide").
    - weaknesses: Points faibles (ex: "Acceptation aveugle de l'IA", "Manque de justification").
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            reasoningScore: { type: Type.INTEGER },
            clarityScore: { type: Type.INTEGER },
            skepticismScore: { type: Type.INTEGER },
            processScore: { type: Type.INTEGER },
            reflectionScore: { type: Type.INTEGER },
            keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["summary", "reasoningScore", "clarityScore", "skepticismScore", "processScore", "reflectionScore", "keyStrengths", "weaknesses"]
        }
      }
    });

    if (response.text) {
      const data = JSON.parse(response.text);
      return {
        ...data,
        transcript,
        aiDeclaration
      };
    }
    throw new Error("Empty response from analysis");

  } catch (error) {
    console.error("Analysis generation failed:", error);
    return {
      summary: "L'analyse automatique n'a pas pu être générée.",
      reasoningScore: 0,
      clarityScore: 0,
      skepticismScore: 0,
      processScore: 0,
      reflectionScore: 0,
      keyStrengths: ["N/A"],
      weaknesses: ["Erreur technique lors de l'analyse"],
      transcript,
      aiDeclaration
    };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Send, StopCircle, RefreshCw, FileSignature, AlertCircle } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { Chat } from "@google/genai";
import { Message, SessionConfig } from '../types';
import { sendMessage } from '../services/gemini';

interface ChatScreenProps {
  chatInstance: Chat | null;
  config: SessionConfig;
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  onFinish: (aiDeclaration: string) => void;
}

const ChatScreen: React.FC<ChatScreenProps> = ({ chatInstance, config, messages, setMessages, onFinish }) => {
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showDeclarationModal, setShowDeclarationModal] = useState(false);
  const [declarationText, setDeclarationText] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Initialize conversation
  useEffect(() => {
    const initChat = async () => {
      if (messages.length === 0 && chatInstance) {
        setIsLoading(true);
        try {
          const introResponse = await sendMessage(chatInstance, "Démarrez la session selon le protocole pédagogique strict.");
          setMessages([
            {
              id: crypto.randomUUID(),
              role: 'model',
              text: introResponse,
              timestamp: Date.now()
            }
          ]);
        } catch (e) {
          console.error(e);
        } finally {
          setIsLoading(false);
        }
      }
    };
    initChat();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [chatInstance]);

  // Auto-scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  const handleSend = async () => {
    if (!inputText.trim() || !chatInstance || isLoading) return;

    const userMsg: Message = {
      id: crypto.randomUUID(),
      role: 'user',
      text: inputText,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);

    try {
      const responseText = await sendMessage(chatInstance, userMsg.text);
      const aiMsg: Message = {
        id: crypto.randomUUID(),
        role: 'model',
        text: responseText,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, aiMsg]);
    } catch (error) {
      console.error("Failed to get response", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleFinishClick = () => {
    setShowDeclarationModal(true);
  };

  const handleSubmitDeclaration = () => {
    onFinish(declarationText || "Aucune déclaration fournie.");
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 relative">
      {/* Declaration Modal Overlay */}
      {showDeclarationModal && (
        <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full p-8 border border-slate-200 animate-in fade-in zoom-in duration-300">
            <div className="flex items-center gap-3 mb-6 text-indigo-600">
              <FileSignature size={32} />
              <h2 className="text-2xl font-bold text-slate-900">Déclaration de Responsabilité</h2>
            </div>

            <div className="bg-indigo-50 border border-indigo-100 rounded-lg p-4 mb-6 text-sm text-indigo-900">
              <p className="font-semibold flex items-center gap-2 mb-2">
                <AlertCircle size={16} />
                Trace de la collaboration Humain-IA (Promptographie)
              </p>
              <p>
                Pour valider cette session, veuillez décrire brièvement comment vous avez utilisé l'IA (ce tuteur ou d'autres outils externes) 
                et copiez-collez les principaux "prompts" utilisés si pertinent. C'est votre "journal de bord" méthodologique.
              </p>
            </div>

            <label className="block text-sm font-medium text-slate-700 mb-2">
              Votre déclaration d'usage et méthodologie :
            </label>
            <textarea
              value={declarationText}
              onChange={(e) => setDeclarationText(e.target.value)}
              placeholder="Ex: J'ai utilisé le DES pour challenger mes idées sur X. J'ai aussi vérifié les faits sur [Source Y]. Voici mon prompt initial : '...'"
              className="w-full h-40 p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 mb-6 resize-none"
            />

            <div className="flex justify-end gap-3">
              <button
                onClick={() => setShowDeclarationModal(false)}
                className="px-5 py-2 text-slate-600 hover:bg-slate-100 rounded-lg font-medium transition-colors"
              >
                Retour au dialogue
              </button>
              <button
                onClick={handleSubmitDeclaration}
                className="px-6 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-bold shadow-md transition-colors flex items-center gap-2"
              >
                Valider et Générer le Rapport
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-10">
        <div>
          <h2 className="text-lg font-bold text-slate-800">Session en cours : {config.topic}</h2>
          <p className="text-xs text-slate-500">Étudiant : {config.studentName} | Mode : {config.mode}</p>
        </div>
        <button
          onClick={handleFinishClick}
          className="flex items-center gap-2 px-4 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-lg transition-colors text-sm font-medium"
        >
          <StopCircle size={16} />
          Terminer & Évaluer
        </button>
      </header>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6">
        {messages.map((msg) => (
          <div
            key={msg.id}
            className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[85%] sm:max-w-[75%] rounded-2xl px-5 py-4 shadow-sm ${
                msg.role === 'user'
                  ? 'bg-indigo-600 text-white rounded-br-none'
                  : 'bg-white text-slate-800 border border-slate-200 rounded-bl-none'
              }`}
            >
              <div className={`prose prose-sm max-w-none ${msg.role === 'user' ? 'prose-invert' : ''}`}>
                 <ReactMarkdown>{msg.text}</ReactMarkdown>
              </div>
              <div className={`text-[10px] mt-2 opacity-70 ${msg.role === 'user' ? 'text-indigo-200' : 'text-slate-400'}`}>
                {msg.role === 'model' ? 'DES Agent' : config.studentName} • {new Date(msg.timestamp).toLocaleTimeString()}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start w-full">
            <div className="bg-white border border-slate-200 rounded-2xl rounded-bl-none px-5 py-4 shadow-sm flex items-center gap-2">
              <RefreshCw className="animate-spin text-slate-400" size={16} />
              <span className="text-sm text-slate-500">Analyse du processus...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-slate-200 p-4 sm:p-6">
        <div className="max-w-4xl mx-auto relative">
          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={handleKeyPress}
            placeholder="Écrivez votre réponse (soyez explicite sur votre raisonnement)..."
            className="w-full bg-slate-100 text-slate-900 rounded-xl pl-4 pr-12 py-3 resize-none focus:outline-none focus:ring-2 focus:ring-indigo-500 border border-transparent focus:border-transparent transition-all"
            rows={1}
            style={{ minHeight: '50px', maxHeight: '150px' }}
          />
          <button
            onClick={handleSend}
            disabled={!inputText.trim() || isLoading}
            className="absolute right-2 bottom-2 p-2 bg-slate-900 text-white rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-800 transition-colors"
          >
            <Send size={18} />
          </button>
        </div>
        <p className="text-center text-xs text-slate-400 mt-2">
          Le système évalue votre processus de pensée, vos justifications et votre esprit critique.
        </p>
      </div>
    </div>
  );
};

