import { GoogleGenAI, Chat, Type } from "@google/genai";
import { Message, SocraticMode, AnalysisData } from "../types";

// Initialize client with process.env.API_KEY directly
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_NAME = 'gemini-2.5-flash';

/**
 * Initializes a chat session with specific system instructions based on the selected mode.
 */
export const createChatSession = (mode: SocraticMode, topic: string): Chat => {
  let systemInstruction = "";

  if (mode === SocraticMode.TUTOR) {
    systemInstruction = `
      Vous êtes le "Dialogue Évaluatif Socratique" (DES).
      Votre rôle : Tuteur exigeant axé sur le PROCESSUS et la MÉTACOGNITION.
      Sujet : ${topic}.

      Protocole pédagogique strict :
      1. DEMANDE D'ÉBAUCHE : Ne demandez pas une réponse finale. Demandez d'abord un plan, une première ébauche ou une hypothèse de travail.
      2. JUSTIFICATION MÉTHODOLOGIQUE : Pour chaque affirmation de l'étudiant, demandez "Pourquoi avoir choisi cette approche ?" ou "Sur quelle preuve repose ce choix ?". Forcez l'étudiant à rendre sa pensée visible.
      3. CONTRADICTION (DÉFENSE ORALE) : Adoptez une posture contradictoire. Attaquez les points faibles de son raisonnement pour simuler une défense orale. L'étudiant doit défendre ses choix "sur le vif".
      4. JOURNAL RÉFLEXIF : Demandez régulièrement : "Avez-vous changé d'avis par rapport à votre idée initiale ? Pourquoi ?".

      Ne donnez JAMAIS la réponse. Évaluez la méthode, pas juste le résultat.
      Commencez par demander à l'étudiant de proposer une première piste de réflexion ou un plan sur le sujet.
    `;
  } else {
    systemInstruction = `
      Vous êtes le "Dialogue Évaluatif Socratique" (DES) en mode "IA-Formateur / Littératie Critique".
      Votre rôle : Générer du contenu plausible mais faillible pour tester la VIGILANCE ÉPISTÉMIQUE de l'étudiant.
      Sujet : ${topic}.

      Protocole pédagogique strict :
      1. LE PIÈGE : Générez une analyse détaillée sur le sujet qui contient des erreurs subtiles (biais logique, hallucination factuelle crédible, ou généralisation abusive).
      2. LA CONSIGNE : Demandez à l'étudiant d'agir comme un expert qui doit valider ce contenu avant publication. Demandez-lui de vérifier les faits et d'identifier les biais.
      3. VÉRIFICATION : Si l'étudiant corrige une erreur, demandez-lui : "Quelles sources avez-vous consultées pour vérifier cela ?" ou "Comment savez-vous que c'est faux ?".
      4. RESPONSABILITÉ : Poussez l'étudiant à critiquer la "boîte noire" de l'IA.

      Commencez par soumettre votre analyse (imparfaite) à l'étudiant.
    `;
  }

  return ai.chats.create({
    model: MODEL_NAME,
    config: {
      systemInstruction: systemInstruction.trim(),
    },
  });
};

/**
 * Sends a message to the active chat session.
 */
export const sendMessage = async (chat: Chat, message: string): Promise<string> => {
  try {
    const response = await chat.sendMessage({ message });
    return response.text || "Erreur de génération de réponse.";
  } catch (error) {
    console.error("Error sending message:", error);
    return "Une erreur est survenue lors de la communication avec l'IA.";
  }
};

/**
 * Analyzes the entire transcript to generate a pedagogical report.
 */
export const generateAnalysis = async (transcript: Message[], topic: string, aiDeclaration: string): Promise<AnalysisData> => {
  const transcriptText = transcript
    .map((m) => `[${m.role === 'user' ? 'Étudiant' : 'DES'}]: ${m.text}`)
    .join('\n');

  const prompt = `
    Analysez cette session de Dialogue Évaluatif Socratique.
    Sujet : "${topic}".

    Déclaration d'usage de l'IA par l'étudiant (Transparence/Agraphie) :
    "${aiDeclaration}"

    Transcription du dialogue :
    ${transcriptText}

    OBJECTIF D'ÉVALUATION :
    Vous devez évaluer le PROCESSUS D'APPRENTISSAGE et non seulement le produit final.
    Cherchez des preuves de :
    1. Itération : L'étudiant a-t-il affiné sa pensée ?
    2. Justification : L'étudiant a-t-il expliqué le "pourquoi" de ses choix ?
    3. Critique : L'étudiant a-t-il remis en cause l'IA ou ses propres biais ?
    4. Responsabilité : La déclaration d'usage est-elle cohérente avec le dialogue ?

    IMPORTANT : TOUS les textes générés dans le JSON doivent impérativement être en FRANÇAIS.

    Format JSON attendu :
    - summary: Résumé narratif axé sur l'évolution de la pensée de l'étudiant.
    - reasoningScore: (0-100) Solidité logique.
    - clarityScore: (0-100) Clarté d'expression.
    - skepticismScore: (0-100) Jugement critique face à l'information.
    - processScore: (0-100) Capacité à itérer, à corriger ses erreurs et à montrer son cheminement.
    - reflectionScore: (0-100) Capacité métacognitive (conscience de sa propre méthode).
    - keyStrengths: Points forts (ex: "Excellente vérification des sources", "Défense orale solide").
    - weaknesses: Points faibles (ex: "Acceptation aveugle de l'IA", "Manque de justification").
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            reasoningScore: { type: Type.INTEGER },
            clarityScore: { type: Type.INTEGER },
            skepticismScore: { type: Type.INTEGER },
            processScore: { type: Type.INTEGER },
            reflectionScore: { type: Type.INTEGER },
            keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["summary", "reasoningScore", "clarityScore", "skepticismScore", "processScore", "reflectionScore", "keyStrengths", "weaknesses"]
        }
      }
    });

    if (response.text) {
      const data = JSON.parse(response.text);
      return {
        ...data,
        transcript,
        aiDeclaration
      };
    }
    throw new Error("Empty response from analysis");

  } catch (error) {
    console.error("Analysis generation failed:", error);
    return {
      summary: "L'analyse automatique n'a pas pu être générée.",
      reasoningScore: 0,
      clarityScore: 0,
      skepticismScore: 0,
      processScore: 0,
      reflectionScore: 0,
      keyStrengths: ["N/A"],
      weaknesses: ["Erreur technique lors de l'analyse"],
      transcript,
      aiDeclaration
    };
  }
};

