          .score-val { font-weight: bold; font-size: 18px; color: #4f46e5; }

          .lists-container { display: flex; gap: 20px; margin-top: 20px; }
          .list-col { flex: 1; }
          ul { padding-left: 20px; margin-top: 10px; }
          li { margin-bottom: 5px; font-size: 14px; }

